40	Status ConvertIpInfos(const std::vector<IpInfo> &ip_infos, std::vector<llm::IpInfo> &ret) {
41	  ret.reserve(ip_infos.size());
42	  for (const auto &ip_info : ip_infos) {
43	    llm::IpInfo llm_ip_info;
44	    LLM_CHK_BOOL_RET_STATUS(ip_info.ip.GetLength() > 0, LLM_PARAM_INVALID, "ip not set");
45	    LLM_CHK_STATUS_RET(llm::LLMUtils::IpToInt(ip_info.ip.GetString(), llm_ip_info.ip),
46	                       "Failed to convert ip:%s to an integer", ip_info.ip.GetString());
47	    llm_ip_info.port = ip_info.port;
48	    ret.emplace_back(llm_ip_info);
49	  }
50	  return LLM_SUCCESS;
51	}
