53	Status ConvertClusterInfos(const std::vector<ClusterInfo> &cluster_infos, std::vector<llm::ClusterInfo> &ret) {
54	  for (size_t i = 0U; i < cluster_infos.size(); ++i) {
55	    const auto &cluster_info = cluster_infos[i];
56	    llm::ClusterInfo llm_cluster_info{};
57	    llm_cluster_info.remote_cluster_id = cluster_info.remote_cluster_id;
58	    llm_cluster_info.remote_role_type = cluster_info.remote_role_type;
59	    LLM_CHK_STATUS_RET(ConvertIpInfos(cluster_info.remote_ip_infos, llm_cluster_info.remote_ip_infos),
60	                       "Failed to parse remote ip info, index = %zu", i);
61	    LLM_CHK_STATUS_RET(ConvertIpInfos(cluster_info.local_ip_infos, llm_cluster_info.local_ip_infos),
62	                       "Failed to parse local ip info, index = %zu", i);
63	    ret.emplace_back(std::move(llm_cluster_info));
64	  }
65	  return LLM_SUCCESS;
66	}
