68	llm::CacheKey ToCacheKey(const CacheIndex &src_cache_index, bool dst_is_cache) {
69	  llm::CacheKey cache_key{};
70	  cache_key.prompt_cluster_id = src_cache_index.cluster_id;
71	  cache_key.prompt_cache_id = src_cache_index.cache_id;
72	  if (dst_is_cache) {
73	    cache_key.prompt_batch_index = src_cache_index.batch_index;
74	  }
