98	static int32_t GetCacheMaxLayer(const Cache &cache, const KvCacheExtParam &ext_param) {
99	  // the range is [a, b], including a and b
100	  int32_t max_layer = 0;
101	  // when num_tensors < tensor_num_per_layer, all treat as one layer, for history default input error case
102	  if (cache.cache_desc.num_tensors >= ext_param.tensor_num_per_layer) {
103	    if (cache.cache_desc.num_tensors % ext_param.tensor_num_per_layer == 0) {
104	      max_layer = static_cast<int32_t>(cache.cache_desc.num_tensors / ext_param.tensor_num_per_layer) - 1;
105	    } else {
106	      // treat last part as one layer, for history default input error case
107	      max_layer = static_cast<int32_t>(cache.cache_desc.num_tensors / ext_param.tensor_num_per_layer);
108	    }
109	  }
110	  return max_layer;
111	}
112	
113	// not calc default layer ranges
114	void CalcIndicesWithValidRanges(const KvCacheExtParam &ext_param, llm::PullCacheParam &pull_cache_param) {
115	  if (ext_param.src_layer_range.first < 0 || ext_param.dst_layer_range.first < 0) {
116	    return;
117	  }
118	
119	  uint64_t indices_beg = static_cast<uint64_t>(ext_param.src_layer_range.first * ext_param.tensor_num_per_layer);
120	  uint64_t range = static_cast<uint64_t>((ext_param.src_layer_range.second - ext_param.src_layer_range.first + 1) *
121	                                         ext_param.tensor_num_per_layer);
122	  for (uint64_t i = 0; i < range; i++) {
123	    pull_cache_param.src_tensor_indices.push_back(indices_beg + i);
124	  }
125	
126	  indices_beg = static_cast<uint64_t>(ext_param.dst_layer_range.first * ext_param.tensor_num_per_layer);
127	  range = static_cast<uint64_t>((ext_param.dst_layer_range.second - ext_param.dst_layer_range.first + 1) *
128	                                ext_param.tensor_num_per_layer);
129	  for (uint64_t i = 0; i < range; i++) {
130	    pull_cache_param.dst_tensor_indices.push_back(indices_beg + i);
131	  }
132	}
