244	Status LlmDataDist::LlmDataDistImpl::PullKvBlocks(const CacheIndex &src_cache_index, const Cache &dst_cache,
245	                                                  const std::vector<uint64_t> &src_blocks,
246	                                                  const std::vector<uint64_t> &dst_blocks,
247	                                                  const KvCacheExtParam &dst_param) {
248	  LLM_CHK_BOOL_RET_STATUS((llm_data_dist_.IsInitialized()), ge::FAILED, "LlmDataDist is not initialized");
249	  llm::PullCacheParam pull_cache_param{};
250	  LLM_CHK_BOOL_RET_STATUS(src_cache_index.batch_index == 0U, LLM_PARAM_INVALID,
251	                          "invalid src_cache_index.batch_index (%u), only 0 is supported in pull block",
252	                          src_cache_index.batch_index);
253	
254	  LLM_CHK_STATUS_RET(CheckKvCacheExtParam(dst_param));
255	
256	  pull_cache_param.prompt_blocks = src_blocks;
257	  pull_cache_param.decoder_blocks = dst_blocks;
258	  pull_cache_param.tensor_num_per_layer = dst_param.tensor_num_per_layer;
259	  CalcIndicesWithValidRanges(dst_param, pull_cache_param);
260	  return llm_data_dist_.PullBlocks(dst_cache.cache_id, ToCacheKey(src_cache_index, dst_blocks.empty()),
261	                                   pull_cache_param);
262	}
