264	Status LlmDataDist::LlmDataDistImpl::PullKvCache(const CacheIndex &src_cache_index, const Cache &dst_cache,
265	                                                 uint32_t batch_index, int64_t size, const KvCacheExtParam &ext_param) {
266	  LLM_CHK_BOOL_RET_STATUS((llm_data_dist_.IsInitialized()), ge::FAILED, "LlmDataDist is not initialized");
267	  LLM_CHK_BOOL_RET_STATUS((size == -1) || (size > 0), LLM_PARAM_INVALID, "Invalid size (%ld), size must = -1 or > 0",
268	                          size);
269	
270	  LLM_CHK_STATUS_RET(CheckKvCacheExtParam(ext_param));
271	
272	  llm::PullCacheParam pull_cache_param{};
273	  pull_cache_param.batch_index = batch_index;
274	  pull_cache_param.size = size;
275	  pull_cache_param.tensor_num_per_layer = ext_param.tensor_num_per_layer;
276	  CalcIndicesWithValidRanges(ext_param, pull_cache_param);
277	  return llm_data_dist_.PullCache(dst_cache.cache_id, ToCacheKey(src_cache_index, true), pull_cache_param);
278	}
