280	Status LlmDataDist::LlmDataDistImpl::SetRole(LlmRole role, const std::map<AscendString, AscendString> &options) {
281	  LLM_CHK_BOOL_RET_STATUS((llm_data_dist_.IsInitialized()), ge::FAILED, "LlmDataDist is not initialized");
282	  const auto &role_str = RoleToString(role);
283	  LLM_CHK_BOOL_RET_STATUS((!role_str.empty()), LLM_PARAM_INVALID, "Invalid role: %d", static_cast<int32_t>(role));
284	  std::map<std::string, std::string> switch_options;
285	  for (const auto &key_and_value : options) {
286	    (void)switch_options.emplace(key_and_value.first.GetString(), key_and_value.second.GetString());
287	  }
288	  std::string ip;
289	  uint32_t port = 0U;
290	  const auto &iter = options.find(llm_datadist::OPTION_LISTEN_IP_INFO);
291	  if (iter != options.cend()) {
292	    LLMLOGI("Target role:%s listen option %s=%s", role_str.c_str(), llm_datadist::OPTION_LISTEN_IP_INFO,
293	            iter->second.GetString());
294	    LLM_CHK_STATUS_RET(llm::LLMUtils::ParseListenIpInfo(options, ip, port), "Failed to parse listen ip info");
295	    switch_options[llm::kLlmOptionListenIp] = ip;
296	    switch_options[llm::kLlmOptionListenPort] = std::to_string(port);
297	  }
298	  const auto ret = llm_data_dist_.SwitchRole(role_str, switch_options);
299	  LLM_CHK_BOOL_RET_STATUS(ret == LLM_SUCCESS, ret, "[SetRole] failed, prev_role = %s, target_role = %s",
300	                          RoleToString(role_).c_str(), role_str.c_str());
301	  LLMLOGI("[SetRole] success, prev_role = %s, target_role = %s", RoleToString(role_).c_str(), role_str.c_str());
302	  role_ = role;
303	  return LLM_SUCCESS;
304	}
