366	Status LlmDataDist::LlmDataDistImpl::PushKvBlocks(const Cache &src_cache, const CacheIndex &dst_cache_index,
367	                                                  const std::vector<uint64_t> &src_blocks,
368	                                                  const std::vector<uint64_t> &dst_blocks,
369	                                                  const KvCacheExtParam &ext_param) {
370	  LLM_CHK_BOOL_RET_STATUS((llm_data_dist_.IsInitialized()), ge::FAILED, "LlmDataDist is not initialized");
371	  LLM_CHK_BOOL_RET_STATUS(src_cache.cache_desc.placement == CachePlacement::kDevice, LLM_PARAM_INVALID,
372	                          "Only support push to device cache");
373	
374	  LLM_CHK_BOOL_RET_STATUS(!src_blocks.empty(), LLM_PARAM_INVALID,
375	                          "src_blocks is empty, push from non-block cache is not supported yet");
376	  LLM_CHK_BOOL_RET_STATUS(src_blocks.size() == dst_blocks.size(), LLM_PARAM_INVALID,
377	                          "number of src_blocks (%zu) mismatches that of dst_blocks (%zu)", src_blocks.size(),
378	                          dst_blocks.size());
379	  LLM_CHK_BOOL_RET_STATUS(dst_cache_index.batch_index == 0U, LLM_PARAM_INVALID,
380	                          "invalid dst_cache_index.batch_index (%u), only 0 is supported in push block",
381	                          dst_cache_index.batch_index);
382	
383	  LLM_CHK_STATUS_RET(CheckKvCacheExtParam(ext_param, true));
384	  LLM_CHK_BOOL_RET_STATUS(((ext_param.src_layer_range.first >= 0) ||
385	                           (ext_param.src_layer_range.first == -1 && src_cache.cache_desc.num_tensors > 0)),
386	                          LLM_PARAM_INVALID, "Invalid src layer:%d, layer need >= 0, or -1 with valid num_tensors.",
387	                          ext_param.src_layer_range.first);
388	
389	  constexpr uint64_t kCacheKeyByIdType = 2UL;
390	  llm::TransferCacheConfig transfer_cache_config{};
391	  transfer_cache_config.src_cache_id = src_cache.cache_id;
392	  transfer_cache_config.cluster_id = dst_cache_index.cluster_id;
393	  transfer_cache_config.dst_cache_id = dst_cache_index.cache_id;
394	  transfer_cache_config.model_id_or_cache_id = dst_cache_index.cache_id;
395	  transfer_cache_config.type = kCacheKeyByIdType;
396	  transfer_cache_config.tensor_num_per_layer = ext_param.tensor_num_per_layer;
397	  llm::TransferBlockConfig transfer_block_config{};
398	  transfer_block_config.src_blocks = src_blocks;
399	  transfer_block_config.dst_blocks = dst_blocks;
400	
401	  return PushData(src_cache, ext_param, transfer_cache_config, transfer_block_config);
402	}
