22	ge::Status LLMDataDistV2::DoInnerInitialize(int32_t device_id, bool remote_cache_accessible,
23	                                            const std::map<ge::AscendString, ge::AscendString> &options) {
24	  LLM_CHK_ACL_RET(aclrtSetDevice(device_id));
25	  hixl::TemporaryRtContext with_context(nullptr);
26	  device_id_ = device_id;
27	  LLM_DISMISSABLE_GUARD(fail_guard, ([this]() {
28	                          if (aclrt_context_ != nullptr) {
29	                            (void)aclrtDestroyContext(aclrt_context_);
30	                            aclrt_context_ = nullptr;
31	                          }
32	                          (void)aclrtResetDevice(device_id_);
33	                          comm_entity_manager_->Finalize();
34	                          comm_mem_manager_->Finalize();
35	                          data_cache_engine_->Finalize();
36	                          GlobalMemManager::GetInstance().Finalize();
37	                        }));
38	  LLM_CHK_ACL_RET(aclrtCreateContext(&aclrt_context_, device_id));
39	  LLMEVENT("Switch new aclrt ctx:%p, device_id:%d", aclrt_context_, device_id_);
40	  LLM_CHK_STATUS_RET(GlobalMemManager::GetInstance().Initialize(transfer_engine_.get()),
41	                     "GlobalMemManager initialize failed.");
42	  LLM_CHK_STATUS_RET(comm_mem_manager_->Initialize(transfer_engine_.get()), "CommMemManager initialize failed.");
43	  LLM_CHK_STATUS_RET(transfer_engine_->Initialize(options), "Transfer engine initialize failed.");
44	  LLM_CHK_STATUS_RET(data_cache_engine_->Initialize(options), "DataCacheEngine initialize failed.");
45	  LLM_CHK_STATUS_RET(comm_entity_manager_->Initialize(!remote_cache_accessible),
46	                     "CommEntityManager initialize failed.");
47	
48	  LlmDatadistTimer::Instance().Init();
49	  statistic_timer_handle_ = LlmDatadistTimer::Instance().CreateTimer([this]() {
50	    CommStatisticManager::GetInstance().Dump();
51	    comm_entity_manager_->Dump();
52	  });
53	  constexpr uint32_t kStatisticTimerPeriod = 80U * 1000U;
54	  (void)LlmDatadistTimer::Instance().StartTimer(statistic_timer_handle_, kStatisticTimerPeriod, false);
55	  LLM_DISMISS_GUARD(fail_guard);
56	  return ge::SUCCESS;
57	}
