59	ge::Status LLMDataDistV2::DoInitialize(const std::map<ge::AscendString, ge::AscendString> &options) {
60	  auto iter = options.find(LLM_OPTION_ROLE);
61	  LLM_ASSERT_TRUE(iter != options.end(), "[LLMDataDist] option:%s not found.", LLM_OPTION_ROLE);
62	  LLMLOGI("LLMDataDist role:%s.", iter->second.GetString());
63	  transfer_engine_ = TransferEngineFactory::Create(options, cluster_id_);
64	  LLM_CHECK_NOTNULL(transfer_engine_);
65	  bool remote_cache_accessible = false;
66	  LLM_CHK_STATUS_RET(LLMUtils::ParseFlag(kLlmOptionEnableRemoteCacheAccessible, options, remote_cache_accessible),
67	                     "Failed to parse option %s", kLlmOptionEnableRemoteCacheAccessible);
68	  int32_t device_id = 0;
69	  LLM_CHK_STATUS_RET(LLMUtils::ParseDeviceId(options, device_id), "Failed to get device id");
70	  cache_manager_ = MakeUnique<CacheManager>();
71	  LLM_CHECK_NOTNULL(cache_manager_);
72	  comm_mem_manager_ = MakeUnique<CommMemManager>();
73	  LLM_CHECK_NOTNULL(comm_mem_manager_);
74	  comm_entity_manager_ = MakeUnique<CommEntityManager>();
75	  LLM_CHECK_NOTNULL(comm_entity_manager_);
76	  transfer_engine_->SetCommEntityManager(comm_entity_manager_.get());
77	  transfer_engine_->SetCacheManager(cache_manager_.get());
78	  data_cache_engine_ = MakeUnique<DataCacheEngine>();
79	  LLM_CHECK_NOTNULL(data_cache_engine_);
80	  data_cache_engine_->SetCommEntityManager(comm_entity_manager_.get());
81	  data_cache_engine_->SetCommMemManager(comm_mem_manager_.get());
82	  data_cache_engine_->SetCacheManager(cache_manager_.get());
83	  LLM_CHK_STATUS_RET(DoInnerInitialize(device_id, remote_cache_accessible, options),
84	                     "Failed to init, device id:%d, cluster:%lu", device_id, cluster_id_);
85	  LLMLOGI("[LLMDataDist] cluster:[%lu] init success", cluster_id_);
86	  inner_initialized_ = true;
87	  return ge::SUCCESS;
88	}
