92	  std::lock_guard<std::mutex> lk(mutex_);
93	  if (!is_initialized_.load()) {
94	    LLM_CHK_STATUS_RET(DoInitialize(options), "Failed to initialize llm datadist, cluster id:%lu", cluster_id_);
