100	void LLMDataDistV2::DoInnerFinalize() {
101	  {
102	    hixl::TemporaryRtContext with_context(aclrt_context_);
103	    comm_entity_manager_->Dump();
104	    transfer_engine_->UnlinkAllClusters();
105	    comm_entity_manager_->Finalize();
106	    comm_mem_manager_->Finalize();
107	    data_cache_engine_->Finalize();
108	    GlobalMemManager::GetInstance().Finalize();
109	    transfer_engine_->Finalize();
110	
111	    CommStatisticManager::GetInstance().Dump();
112	    CommStatisticManager::GetInstance().Reset();
113	    if (statistic_timer_handle_ != nullptr) {
114	      (void)LlmDatadistTimer::Instance().StopTimer(statistic_timer_handle_);
115	      (void)LlmDatadistTimer::Instance().DeleteTimer(statistic_timer_handle_);
116	      statistic_timer_handle_ = nullptr;
117	    }
118	    LlmDatadistTimer::Instance().Finalize();
119	  }
120	  if (aclrt_context_ != nullptr) {
121	    (void)aclrtDestroyContext(aclrt_context_);
122	    aclrt_context_ = nullptr;
123	  }
124	
125	  if (device_id_ != -1) {
126	    LLM_CHK_ACL(aclrtResetDevice(device_id_));
127	    device_id_ = -1;
128	  }
129	  inner_initialized_.store(false);
130	}
131	
132	void LLMDataDistV2::DoFinalize() {
133	  DoInnerFinalize();
134	}
