136	void LLMDataDistV2::LLMDataDistFinalize() {
137	  std::lock_guard<std::mutex> lk(mutex_);
138	  if (!is_initialized_.load()) {
139	    LLMLOGW("[LLMDataDist] cluster:%lu is not initialized", cluster_id_);
140	    return;
141	  }
142	  DoFinalize();
143	  is_initialized_.store(false);
144	  LLMLOGI("LLMDataDist Finalize end.");
145	}
