ge::Status LLMDataDistV2::SwitchRole(const std::string &role, const std::map<std::string, std::string> &options) const {
  LLM_CHK_BOOL_RET_STATUS(is_initialized_.load(std::memory_order::memory_order_relaxed), ge::FAILED,
