45	static void from_json(const nlohmann::json &j, ExchangeMemInfo &e) {
46	  j.at("cache_table_addr").get_to(e.cache_table_addr);
47	  j.at("cache_table_size").get_to(e.cache_table_size);
48	  j.at("req_addr").get_to(e.req_addr);
