64	ge::Status CommLinkManager::ExchangeMem(const EntityPtr &entity, uint32_t local_rank, uint32_t remote_rank) const {
65	  ExchangeMemInfo local_mem_info{};
66	  const auto &buffer_and_size = cache_manager_->GetCacheTableBufferAndSize();
67	  local_mem_info.cache_table_addr = PtrToValue(buffer_and_size.first);
68	  local_mem_info.cache_table_size = buffer_and_size.second;
69	  local_mem_info.req_addr = PtrToValue(entity->GetReq());
70	  local_mem_info.req_size = kDefaultReqBufferSize;
71	  local_mem_info.resp_addr = PtrToValue(entity->GetResp());
72	  local_mem_info.resp_size = kDefaultRespBufferSize;
73	  std::string mem_info_str;
74	  try {
75	    nlohmann::json j = local_mem_info;
76	    mem_info_str = j.dump();
77	  } catch (const nlohmann::json::exception &e) {
78	    LLMLOGE(ge::LLM_PARAM_INVALID, "Failed to dump msg to str, exception:%s", e.what());
79	    return ge::LLM_PARAM_INVALID;
80	  }
81	  HcclMemDesc local_desc{};
82	  local_desc.localRank = local_rank;
83	  local_desc.remoteRank = remote_rank;
84	  HcclMemDesc remote_desc{};
85	  LLM_ASSERT_EOK(strcpy_s(local_desc.desc, HCCL_MEM_DESC_LENGTH, mem_info_str.c_str()));
86	  HcclMemDescs local_descs{&local_desc, 1U};
87	  HcclMemDescs remote_descs{&remote_desc, 1U};
88	  uint32_t remote_mem_num = 0U;
89	  LLMLOGI("start call DlHcclExchangeMemDesc, remote_rank:%u", remote_rank);
90	  int32_t timeout = link_total_time_ > 0 ? link_total_time_ : 30;
91	  HcclResult ret = CommAdapter::GetInstance().DlHcclExchangeMemDesc(entity->GetComm(), remote_rank, &local_descs,
92	                                                                    timeout, &remote_descs, &remote_mem_num);
93	  LLM_CHK_BOOL_RET_STATUS(ret == HcclResult::HCCL_SUCCESS, ge::LLM_LINK_FAILED,
94	                          "Call DlHcclExchangeMemDesc failed, ret:%d", ret);
95	  LLMLOGI("DlHcclExchangeMemDesc suc, remote num:%u", remote_mem_num);
96	  ExchangeMemInfo remote_mem_info{};
97	  try {
98	    auto desc_len = strnlen(remote_desc.desc, HCCL_MEM_DESC_LENGTH);
99	    auto j = nlohmann::json::parse(remote_desc.desc, remote_desc.desc + desc_len);
100	    remote_mem_info = j.get<ExchangeMemInfo>();
101	  } catch (const nlohmann::json::exception &e) {
102	    LLMLOGE(ge::LLM_PARAM_INVALID, "Failed to load exchange mem info, exception:%s", e.what());
103	    return ge::LLM_PARAM_INVALID;
104	  }
105	  LLM_CHK_BOOL_RET_STATUS(remote_mem_info.cache_table_size <= kCacheAccessTableBufferSize, ge::LLM_PARAM_INVALID,
106	                          "Remote cache_table_size %lu exceeds max %lu", remote_mem_info.cache_table_size,
107	                          kCacheAccessTableBufferSize);
108	  std::vector<CommMem> &remote_mems = entity->GetRemoteMems();
109	  CommMem mem{};
110	  SetMemAttribute(remote_mem_info, remote_mems, mem);
111	  return ge::SUCCESS;
112	}
