114	void CommLinkManager::SetMemAttribute(const ExchangeMemInfo &remote_mem_info, std::vector<CommMem> &remote_mems,
115	                                      CommMem &mem) {
116	  mem.type = CommMemType::COMM_MEM_TYPE_DEVICE;
117	  mem.addr = ValueToPtr(remote_mem_info.cache_table_addr);
118	  mem.size = remote_mem_info.cache_table_size;
119	  remote_mems.emplace_back(mem);
120	  mem.type = CommMemType::COMM_MEM_TYPE_HOST;
121	  mem.addr = ValueToPtr(remote_mem_info.req_addr);
122	  mem.size = remote_mem_info.req_size;
123	  remote_mems.emplace_back(mem);
124	  mem.type = CommMemType::COMM_MEM_TYPE_HOST;
125	  mem.addr = ValueToPtr(remote_mem_info.resp_addr);
126	  mem.size = remote_mem_info.resp_size;
127	  remote_mems.emplace_back(mem);
128	}
