130	void CommLinkManager::CheckUnlink(PrepareMemArg &req, bool &check_unlink_flag) {
131	  std::lock_guard<std::mutex> lock(map_mutex_);
132	  if (comm_to_status_[req.comm_id].unlink_flag.load()) {
133	    comm_to_status_[req.comm_id].prepare_mem_flag.store(false);
134	    LLMLOGI("Check exist unlink flag, abort preparing memory.");
135	    check_unlink_flag = true;
136	  }
