139	ge::Status CommLinkManager::DestroyRes(EntityCommInfoPtr comm_ptr, std::vector<EntityPtr> &comm_entities) const {
140	  LLMLOGI("Start call DestroyRes");
141	  ge::Status unlink_ret = ge::SUCCESS;
142	  LLM_CHK_BOOL_EXEC(aclrtSetCurrentContext(aclrt_context_) == ACL_ERROR_NONE, unlink_ret = ge::LLM_UNLINK_FAILED);
143	  for (const auto &entity : comm_entities) {
144	    std::lock_guard<std::mutex> pull_lock(entity->GetPullMutex());
145	    std::lock_guard<std::mutex> process_lock(entity->GetProcessMutex());
146	    auto entity_ret = entity->Finalize();
147	    unlink_ret = entity_ret != ge::SUCCESS ? ge::LLM_UNLINK_FAILED : unlink_ret;
148	    entity->MarkEntityDestroyed();
149	  }
150	  if (remote_cache_accessible_) {
151	    LLMLOGI("Start delete entities.");
152	    comm_entity_manager_->DeleteEntities();
153	  }
154	  if (comm_ptr != nullptr) {
155	    auto comm_ret = comm_ptr->Finalize();
156	    unlink_ret = comm_ret != ge::SUCCESS ? ge::LLM_UNLINK_FAILED : unlink_ret;
157	  }
158	  return unlink_ret;
159	}
