189	ge::Status CommLinkManager::CreateClustersEntity(PrepareMemArg &req, std::map<uint64_t, EntityPtr> &cluster2entity) {
190	  auto local_rank_id = req.cluster2rank[cluster_id_];
191	  for (auto &iter : req.cluster2rank) {
192	    if (iter.first != cluster_id_) {
193	      // create comm entity
194	      EntityPtr entity = MakeShared<CommEntity>(req.comm_id, iter.first, iter.second, cluster_id_, local_rank_id);
195	      LLM_CHECK_NOTNULL(entity);
196	      LLM_CHK_STATUS_RET(entity->Initialize(remote_cache_accessible_), "Failed to init entity");
197	      LLMLOGI("Success to create comm entity:%s", entity->GetDesc().c_str());
198	      auto mem_info_ptr = MakeUnique<EntityMemInfo>(remote_cache_accessible_, comm_entity_manager_->GetHostRegPool(),
199	                                                    comm_entity_manager_->GetDeviceRegPool());
200	      LLM_CHECK_NOTNULL(mem_info_ptr);
201	      LLM_CHK_STATUS_RET(mem_info_ptr->Initialize(), "Failed to init mem info");
202	      entity->SetEntityMemInfo(mem_info_ptr);
203	      entity->SetCacheManager(cache_manager_);
204	      entity->SetContext(aclrt_context_);
205	      cluster2entity[iter.first] = entity;
206	    }
207	  }
208	  return ge::SUCCESS;
209	}
210	
211	ge::Status CommLinkManager::PrepareMem(PrepareMemArg &req) {
212	  {
213	    std::lock_guard<std::mutex> lock(map_mutex_);
214	    // already unlinked.
215	    LLM_CHK_BOOL_RET_STATUS(comm_to_status_.find(req.comm_id) != comm_to_status_.end(), ge::FAILED,
216	                            "Failed to prepare memory because comm_id:%lu does not exist", req.comm_id);
217	    comm_to_status_[req.comm_id].prepare_mem_flag.store(true);
218	  }
219	  bool check_unlink_flag = false;
220	  CheckUnlink(req, check_unlink_flag);
221	  LLM_CHK_BOOL_RET_STATUS(!check_unlink_flag, ge::FAILED,
222	                          "Failed to prepare memory because comm_id:%lu is being unlinked", req.comm_id);
223	  LLM_MAKE_GUARD(free_flag, ([this, &req]() { FreeFlagGuard(req); }));
224	  LLM_ASSERT_RT_OK(aclrtSetCurrentContext(aclrt_context_));
225	  std::map<uint64_t, EntityPtr> cluster2entity;
226	  ScopeGuard entity_guard([&cluster2entity]() {
227	    for (auto &iter : cluster2entity) {
228	      (void)iter.second->Finalize();
229	    }
230	  });
231	  LLM_CHK_STATUS_RET(CreateClustersEntity(req, cluster2entity), "Failed to create clusters entity.");
232	  EntityCommInfoPtr comm_info_ptr = nullptr;
233	  FreeFlagGuard(req);
234	  LLM_CHK_STATUS_RET(PrepareComm(req, comm_info_ptr), "Failed to prepare comm info");
235	  FlagGuard(req);
236	  LogPrepareMemTargets(req);
237	  std::vector<EntityPtr> new_entities;
238	  auto local_rank_id = req.cluster2rank[cluster_id_];
239	  for (auto &iter : req.cluster2rank) {
240	    if (iter.first != cluster_id_) {
241	      CheckUnlink(req, check_unlink_flag);
242	      auto entity = cluster2entity[iter.first];
243	      entity->SetEntityCommInfo(comm_info_ptr);
244	      LLM_CHK_STATUS_RET(ExchangeMem(entity, local_rank_id, iter.second), "Failed to exchange mem");
245	      LLM_CHK_STATUS_RET(entity->SetInfo(), "Failed to set entity info");
246	      LLM_CHK_STATUS_RET(comm_entity_manager_->AddEntity(iter.first, entity), "Failed to add entity");
247	      (void)new_entities.emplace_back(entity);
248	    }
249	  }
250	  for (auto &entity : new_entities) {
251	    std::lock_guard<std::mutex> process_lock(entity->GetProcessMutex());
252	    entity->MarkEntityIdle();
253	  }
254	  entity_guard.Dismiss();
255	  return ge::SUCCESS;
256	}
257	
258	ge::Status CommLinkManager::PrepareMemTask(CommLinkManager *link_manager, PrepareMemArg request) {
259	  LLMLOGI("New prepare mem request arrived.");
260	  const auto start = std::chrono::steady_clock::now();
261	  auto ret = link_manager->PrepareMem(request);
262	  const auto end = std::chrono::steady_clock::now();
263	  auto count = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();
264	  LLMLOGI("Prepare mem time cost:%ld us", count);
265	  return ret;
266	}
267	
268	void CommLinkManager::UnlinkAll() {
269	  LLMLOGI("Unlink all start.");
270	  std::vector<uint64_t> comm_ids;
271	  {
272	    std::lock_guard<std::mutex> map_lock(map_mutex_);
273	    for (auto &comm_to_status : comm_to_status_) {
274	      comm_ids.emplace_back(comm_to_status.first);
275	    }
276	  }
277	  for (auto comm_id : comm_ids) {
278	    Unlink(comm_id);
279	  }
280	  LLMLOGI("Unlink all end.");
281	}
282	
283	void CommLinkManager::Finalize() {
284	  LLMLOGI("CommLinkManager finalize start, start stop thread.");
285	  running_ = false;
286	  UnlinkAll();
287	  thread_pool_.Destroy();
288	
289	  LLMLOGI("Deregister global mem start");
290	  std::lock_guard<std::mutex> lock(handles_mutex_);
291	  for (auto handle : handles_) {
292	    (void)CommAdapter::GetInstance().DlHcclDeregisterGlobalMem(handle);
293	  }
294	  handles_.clear();
295	  LLMLOGI("Deregister global mem end");
296	}
297	
298	ge::Status CommLinkManager::Initialize(const std::map<ge::AscendString, ge::AscendString> &options) {
299	  LLM_ASSERT_RT_OK(aclrtGetCurrentContext(&aclrt_context_));
300	  const auto it = options.find(LLM_OPTION_RDMA_TRAFFIC_CLASS);
301	  if (it != options.end()) {
302	    LLM_CHK_STATUS_RET(LLMUtils::ToNumber(it->second.GetString(), rdmaTrafficClass_),
303	                       "llm.RdmaTrafficClass is invalid, value = %s", it->second.GetString());
304	    hasTrafficClass_ = true;
305	  }
306	  const auto serviceLevelIter = options.find(LLM_OPTION_RDMA_SERVICE_LEVEL);
307	  if (serviceLevelIter != options.end()) {
308	    LLM_CHK_STATUS_RET(LLMUtils::ToNumber(serviceLevelIter->second.GetString(), rdmaServiceLevel_),
309	                       "llm.RdmaServiceLevel is invalid, value = %s", serviceLevelIter->second.GetString());
310	    hasServiceLevel_ = true;
311	  }
312	  const auto total_time = options.find(LLM_OPTION_LINK_TOTAL_TIME);
313	  if (total_time != options.end()) {
314	    LLM_CHK_STATUS_RET(LLMUtils::ToNumber(total_time->second.GetString(), link_total_time_),
315	                       "llm.linkTotalTime is invalid, value = %s", total_time->second.GetString());
316	  }
317	  const auto retry_count = options.find(LLM_OPTION_LINK_RETRY_COUNT);
318	  if (retry_count != options.end()) {
319	    LLM_CHK_STATUS_RET(LLMUtils::ToNumber(retry_count->second.GetString(), link_retry_count_),
320	                       "llm.linkRetryCount is invalid, value = %s", retry_count->second.GetString());
321	    LLM_CHK_BOOL_RET_STATUS(
322	        link_retry_count_ >= kLinkRetryCountMin && link_retry_count_ <= kLinkRetryCountMax, ge::LLM_PARAM_INVALID,
323	        "llm.linkRetryCount should be an integer between [1, 100], given value is %d", link_retry_count_);
324	  }
325	  return ge::SUCCESS;
326	}
