332	ge::Status CommLinkManager::Link(std::string &cluster_name, const std::map<uint64_t, uint32_t> &cluster2rank,
333	                                 std::string &rank_table, uint64_t &comm_id) {
334	  LLM_CHK_BOOL_RET_STATUS(!cluster_name.empty(), ge::LLM_PARAM_INVALID, "param cluster_name can not be empty.");
335	  LLM_CHK_BOOL_RET_STATUS(cluster_name.size() < COMM_NAME_MAX_LENGTH, ge::LLM_PARAM_INVALID,
336	                          "param cluster_name size should be smaller than:%u", COMM_NAME_MAX_LENGTH);
337	  LLM_CHK_BOOL_RET_STATUS(cluster2rank.find(cluster_id_) != cluster2rank.end(), ge::LLM_PARAM_INVALID,
338	                          "local cluster id does not exist in cluster2rank");
339	  // lock for process
340	  std::lock_guard<std::mutex> lock(mutex_);
341	  {
342	    std::lock_guard<std::mutex> map_lock(map_mutex_);
343	    LLM_CHK_BOOL_RET_STATUS(comm_to_status_.size() < kMaxLinkNum, ge::LLM_PARAM_INVALID, "Link num is over limit:%u.",
344	                            kMaxLinkNum);
345	  }
346	  auto local_rank = cluster2rank.at(cluster_id_);
347	  LLM_CHK_BOOL_RET_STATUS(aclrtSetCurrentContext(aclrt_context_) == ACL_ERROR_NONE, ge::LLM_UNLINK_FAILED,
348	                          "Set aclrt context failed.");
349	  HcclCommConfig config{};
350	  CommAdapter::GetInstance().DlHcclCommConfigInit(&config);
351	  LLM_ASSERT_EOK(strcpy_s(config.hcclCommName, COMM_NAME_MAX_LENGTH, cluster_name.data()));
352	  if (hasTrafficClass_) {
353	    LLMLOGI("Set rdma traffic class to %u.", rdmaTrafficClass_);
354	    config.hcclRdmaTrafficClass = rdmaTrafficClass_;
355	  }
356	  if (hasServiceLevel_) {
357	    LLMLOGI("Set rdma service level to %u.", rdmaServiceLevel_);
358	    config.hcclRdmaServiceLevel = rdmaServiceLevel_;
359	  }
360	
361	  LLMLOGI("DlHcclCommInitClusterInfoMemConfig begin, comm_name=%s, local rank_id=%u, rank_table=%s",
362	          config.hcclCommName, local_rank, rank_table.c_str());
363	  HcclComm comm{};
364	  HcclResult ret =
365	      CommAdapter::GetInstance().DlHcclCommInitClusterInfoMemConfig(rank_table.c_str(), local_rank, &config, &comm);
366	  LLM_CHK_BOOL_RET_STATUS(ret == HcclResult::HCCL_SUCCESS, ge::LLM_LINK_FAILED,
367	                          "Call DlHcclCommInitClusterInfoMemConfig failed, ret:%d.", ret);
368	
369	  comm_id = GenerateCommId();
370	  {
371	    std::lock_guard<std::mutex> map_lock(map_mutex_);
372	    auto &comm_status = comm_to_status_[comm_id];
373	    comm_status.unlink_flag.store(false);
374	    comm_status.prepare_mem_flag.store(false);
375	    comm_status.status = RegisterMemoryStatus::PREPARING;
376	    PrepareMemArg prepare_mem_arg{comm_id,          comm, cluster2rank, GetAllRegisterMemHandles(), link_total_time_,
377	                                  link_retry_count_};
378	    auto fut = thread_pool_.commit(&CommLinkManager::PrepareMemTask, this, prepare_mem_arg);
379	    comm_status.task_fut = std::move(fut);
380	  }
381	  LLMLOGI("Init comm success, comm id:%lu.", comm_id);
382	  return ge::SUCCESS;
383	}
384	
385	ge::Status CommLinkManager::Unlink(uint64_t comm_id) {
386	  ge::Status ret;
387	  // lock for process
388	  std::lock_guard<std::mutex> lock(mutex_);
389	  {
390	    std::lock_guard<std::mutex> map_lock(map_mutex_);
391	    auto iter = comm_to_status_.find(comm_id);
392	    LLM_CHK_BOOL_RET_STATUS(iter != comm_to_status_.end(), ge::LLM_NOT_YET_LINK, "Comm:%lu is not yet link.", comm_id);
393	    iter->second.unlink_flag.store(true);
394	  }
395	  LLMLOGI("Start unlink, comm_id:%lu", comm_id);
396	  while (true) {
397	    {
398	      std::lock_guard<std::mutex> map_lock(map_mutex_);
399	      // check exist before.
400	      auto &comm_status = comm_to_status_[comm_id];
401	      if (!comm_status.prepare_mem_flag.load()) {
402	        LLMLOGI("Can unlink now.");
403	        std::vector<EntityPtr> entities = comm_entity_manager_->QueryEntityByCommId(comm_id);
404	        ret = DestroyRes(comm_status.comm_ptr, entities);
405	        break;
406	      }
407	    }
408	    LLMLOGD("Wait prepare mem end.");
409	    // wait prepare mem thread abort
410	    std::this_thread::sleep_for(std::chrono::milliseconds(kDefaultSleepTime));
411	  }
412	
413	  std::future<ge::Status> task_fut;
414	  {
415	    std::lock_guard<std::mutex> map_lock(map_mutex_);
416	    auto &comm_status = comm_to_status_[comm_id];
417	    task_fut = std::move(comm_status.task_fut);
418	    (void)comm_to_status_.erase(comm_id);
419	  }
420	
421	  if (task_fut.valid()) {
422	    task_fut.get();
423	  }
424	  LLMLOGI("Call unlink done for comm id:%lu", comm_id);
425	  return ret;
426	}
427	
428	ge::Status CommLinkManager::QueryRegisterMemStatus(uint64_t comm_id, RegisterMemoryStatus &status) {
429	  auto ret = ge::LLM_NOT_YET_LINK;
430	  std::lock_guard<std::mutex> lock(map_mutex_);
431	  auto iter = comm_to_status_.find(comm_id);
432	  if (iter != comm_to_status_.end()) {
433	    status = iter->second.status;
434	    if (status == RegisterMemoryStatus::PREPARING && iter->second.task_fut.valid() &&
435	        iter->second.task_fut.wait_for(std::chrono::microseconds(1)) == std::future_status::ready) {
436	      auto prepare_ret = iter->second.task_fut.get();
437	      status = (prepare_ret == ge::SUCCESS) ? RegisterMemoryStatus::OK : RegisterMemoryStatus::FAILED;
438	      iter->second.status = status;
439	    }
440	    ret = ge::SUCCESS;
441	  }
442	  return ret;
443	}
