453	ge::Status CommLinkManager::RegisterMem(CommMem *mem, void **mem_handle) {
454	  auto ret = CommAdapter::GetInstance().DlHcclRegisterGlobalMem(mem, mem_handle);
455	  LLM_CHK_BOOL_RET_STATUS(ret == HCCL_SUCCESS, ge::FAILED, "Failed to invoke DlHcclRegisterGlobalMem, ret = %d",
456	                          static_cast<int32_t>(ret));
457	  LLMLOGI("Register global mem success, addr:%p, size:%lu, type:%d, handle:%p", mem->addr, mem->size,
458	          static_cast<int32_t>(mem->type), *mem_handle);
459	
460	  std::lock_guard<std::mutex> lock(handles_mutex_);
461	  handles_.emplace(*mem_handle);
462	  return ge::SUCCESS;
463	}
464	
465	ge::Status CommLinkManager::DeregisterGlobalMem(void *mem_handle) {
466	  std::lock_guard<std::mutex> lock(handles_mutex_);
467	  auto it = handles_.find(mem_handle);
468	  if (it == handles_.end()) {
469	    LLMLOGW("Mem handle:%p is not registered.", mem_handle);
470	    return ge::SUCCESS;
471	  }
472	  auto ret = CommAdapter::GetInstance().DlHcclDeregisterGlobalMem(mem_handle);
473	  LLM_CHK_BOOL_RET_STATUS(ret == HCCL_SUCCESS, ge::FAILED, "Failed to invoke DlHcclDeregisterGlobalMem, ret = %d",
474	                          static_cast<int32_t>(ret));
475	  handles_.erase(it);
476	  return ge::SUCCESS;
477	}
