22	namespace llm {
23	namespace {
24	const std::string kConfigVersion = "version";
25	constexpr const char kConfigVersionV1[] = "1.0";
26	constexpr const char kConfigVersionV2[] = "1.2";
27	constexpr uint32_t kVersionMaxLen = 32U;
28	}  // namespace
29	
30	std::unique_ptr<RankTableGenerator> RankTableGeneratorFactory::Create(const std::string &local_comm_res,
31	                                                                      const std::string &peer_comm_res) {
32	  nlohmann::json local_res;
33	  nlohmann::json peer_res;
34	  std::string local_version;
35	  std::string peer_version;
36	  try {
37	    if (!rank_table_json::IsCommResJsonSizeValid(local_comm_res) ||
38	        !rank_table_json::IsCommResJsonSizeValid(peer_comm_res)) {
39	      LLMLOGE(ge::LLM_PARAM_INVALID, "comm_res size exceeds limit");
40	      return nullptr;
41	    }
42	    local_res = rank_table_json::ParseCommResJson(local_comm_res);
43	    peer_res = rank_table_json::ParseCommResJson(peer_comm_res);
44	    LLMUtils::AssignRequired(local_version, kConfigVersion, local_res);
45	    LLMUtils::AssignRequired(peer_version, kConfigVersion, peer_res);
46	  } catch (const nlohmann::json::exception &e) {
47	    LLMLOGE(ge::LLM_PARAM_INVALID, "Invalid json, exception:%s", e.what());
48	    return nullptr;
49	  }
50	
51	  if ((local_version != kConfigVersionV1 && local_version != kConfigVersionV2) ||
52	      (peer_version != kConfigVersionV1 && peer_version != kConfigVersionV2)) {
53	    LLMLOGE(ge::LLM_PARAM_INVALID, "version in option:%s only support %s and %s, local version:%s, peer version:%s.",
54	            llm_datadist::OPTION_LOCAL_COMM_RES, kConfigVersionV1, kConfigVersionV2, local_version.c_str(),
55	            peer_version.c_str());
56	    return nullptr;
57	  }
58	
59	  auto version = std::min(local_version, peer_version);
60	  if (version == kConfigVersionV1) {
61	    return MakeUnique<RankTableGeneratorV1>(local_comm_res, peer_comm_res);
62	  }
63	  return MakeUnique<RankTableGeneratorV2>(local_comm_res, peer_comm_res);
64	}
65	
66	ge::Status LocalCommResGenerator::Generate(const std::string &server_id, int32_t device_id, std::string &local_comm_res,
67	                                           std::optional<uint32_t> device_port) {
68	  const static std::set<std::string> kV2Version = {"Ascend910_9391", "Ascend910_9381", "Ascend910_9392",
69	                                                   "Ascend910_9382", "Ascend910_9372", "Ascend910_9362"};
70	  const char *version = aclrtGetSocName();
71	  LLM_CHECK_NOTNULL(version, "aclrt get soc name");
72	  const auto &it = kV2Version.find(version);
73	  if (it != kV2Version.cend()) {
74	    LLM_CHK_STATUS_RET(RankTableGeneratorV2::GenerateLocalCommRes(server_id, device_id, local_comm_res, device_port),
75	                       "Failed to generate local comm res, server_id:%s, device_id:%d.", server_id.c_str(), device_id);
76	  } else {
77	    LLM_CHK_STATUS_RET(RankTableGeneratorV1::GenerateLocalCommRes(server_id, device_id, local_comm_res, device_port),
78	                       "Failed to generate local comm res, server_id:%s, device_id:%d.", server_id.c_str(), device_id);
79	  }
80	  return ge::SUCCESS;
81	}
82	
83	}  // namespace llm
