81	ge::Status LinkMsgHandler::Serialize(const T &msg, std::string &msg_str) {
82	  try {
83	    nlohmann::json j = msg;
84	    msg_str = j.dump();
85	  } catch (const nlohmann::json::exception &e) {
86	    LLMLOGE(ge::LLM_PARAM_INVALID, "Failed to dump msg to str, exception:%s", e.what());
87	    return ge::LLM_PARAM_INVALID;
88	  }
89	  return ge::SUCCESS;
90	}
