92	template <typename T>
93	ge::Status LinkMsgHandler::Deserialize(const std::vector<char> &msg_str, T &msg) {
94	  try {
95	    auto j = nlohmann::json::parse(msg_str.data(), msg_str.data() + msg_str.size());
96	    msg = j.get<T>();
97	  } catch (const nlohmann::json::exception &e) {
98	    LLMLOGE(ge::LLM_PARAM_INVALID, "Failed to load msg, exception:%s", e.what());
99	    return ge::LLM_PARAM_INVALID;
100	  }
101	  return ge::SUCCESS;
102	}
