104	ge::Status LinkMsgHandler::Initialize(const std::map<ge::AscendString, ge::AscendString> &options) {
105	  LLM_CHECK_NOTNULL(comm_entity_manager_);
106	  LLM_CHECK_NOTNULL(cache_manager_);
107	  LLM_CHK_STATUS_RET(LLMUtils::ParseFlag(kLlmOptionEnableRemoteCacheAccessible, options, remote_cache_accessible_),
108	                     "Failed to parse option %s", kLlmOptionEnableRemoteCacheAccessible);
109	  const auto &ip_iter = options.find(kLlmOptionListenIp);
110	  if (ip_iter != options.cend()) {
111	    local_ip_ = ip_iter->second.GetString();
112	  }
113	  const auto &it = options.find(llm_datadist::OPTION_LOCAL_COMM_RES);
114	  if (it != options.cend()) {
115	    local_comm_res_ = it->second.GetString();
116	  }
117	  if (local_comm_res_.empty() && (!local_ip_.empty())) {
118	    LLM_CHK_STATUS_RET(LocalCommResGenerator::Generate(local_ip_, device_id_, local_comm_res_),
119	                       "Failed to generate local comm res, local_ip:%s, device_id:%d", local_ip_.c_str(), device_id_);
120	  }
121	  CommAdapter::GetInstance().DlHcclCommConfigInit(&comm_config_);
122	  const auto &traffic_it = options.find(kOptionRdmaTrafficClass);
123	  if (traffic_it != options.cend()) {
124	    uint32_t traffic_class = 0U;
125	    LLM_CHK_STATUS_RET(LLMUtils::ToNumber(traffic_it->second.GetString(), traffic_class),
126	                       "llm.RdmaTrafficClass is invalid, value = %s", traffic_it->second.GetString());
127	    comm_config_.hcclRdmaTrafficClass = traffic_class;
128	    LLMLOGI("set rdma traffic class to %u.", traffic_class);
129	  }
130	  const auto &service_it = options.find(kOptionRdmaServiceLevel);
131	  if (service_it != options.cend()) {
132	    uint32_t service_level = 0U;
133	    LLM_CHK_STATUS_RET(LLMUtils::ToNumber(service_it->second.GetString(), service_level),
134	                       "llm.RdmaServiceLevel is invalid, value = %s", service_it->second.GetString());
135	    comm_config_.hcclRdmaServiceLevel = service_level;
136	    LLMLOGI("set rdma service level to %u.", service_level);
137	  }
138	  LLM_ASSERT_RT_OK(aclrtGetCurrentContext(&aclrt_context_));
139	  handler_plugin_.Initialize();
140	  return ge::SUCCESS;
141	}
