178	ge::Status LinkMsgHandler::ProcessConnectRequest(int32_t fd, const std::vector<char> &msg) {
179	  EntityMemInfoPtr mem_info_ptr = nullptr;
180	  LLM_CHK_STATUS_RET(CreateEntityMemInfo(mem_info_ptr), "Failed to create entity mem info");
181	  LLMExchangeInfo exchange_info = {};
182	  const auto &buffer_and_size = cache_manager_->GetCacheTableBufferAndSize();
183	  exchange_info.cache_table_addr = PtrToValue(buffer_and_size.first);
184	  exchange_info.cache_table_size = static_cast<uint64_t>(buffer_and_size.second);
185	  exchange_info.comm_res = local_comm_res_;
186	  exchange_info.cluster_id = cluster_id_;
187	  exchange_info.req_addr = PtrToValue(mem_info_ptr->req_);
188	  exchange_info.req_size = kDefaultReqBufferSize;
189	  exchange_info.resp_addr = PtrToValue(mem_info_ptr->resp_);
190	  exchange_info.resp_size = kDefaultRespBufferSize;
191	  LLM_CHK_STATUS_RET(SendMsg(fd, LinkMsgType::kConnect, exchange_info), "Failed to send connect msg");
192	
193	  auto ret = ge::SUCCESS;
194	  LLM_MAKE_GUARD(send_status, ([fd, &ret]() {
195	                   LLMLinkStatus status{};
196	                   status.error_code = ret;
197	                   LinkMsgHandler::SendMsg(fd, LinkMsgType::kStatus, status);
198	                 }));
199	
200	  LLMExchangeInfo peer_exchange_info{};
201	  LLM_CHK_STATUS_RET(LinkMsgHandler::Deserialize(msg, peer_exchange_info), "Failed to deserialize connect msg");
202	  LLMLOGI("Start to process link cluster, local cluster_id:%lu, remote cluster_id:%lu, timeout:%d ms.", cluster_id_,
203	          peer_exchange_info.cluster_id, peer_exchange_info.timeout);
204	  peer_exchange_info.comm_name =
205	      "llm_datadist_" + std::to_string(peer_exchange_info.cluster_id) + "_" + std::to_string(cluster_id_);
206	  ret =
207	      ExchangeInfoProcess(peer_exchange_info, peer_exchange_info.timeout, peer_exchange_info.force_link, mem_info_ptr);
208	  if (ret == ge::SUCCESS) {
209	    LLMLOGI("Success to process link cluster, local cluster_id:%lu, remote cluster_id:%lu.", cluster_id_,
210	            peer_exchange_info.cluster_id);
211	  }
212	  LLM_CHK_STATUS(ret, "Failed to process peer exchange info, timeout:%d ms", peer_exchange_info.timeout);
213	  return ret;
214	}
215	
216	ge::Status LinkMsgHandler::ProcessDisconnectRequest(int32_t fd, const std::vector<char> &msg) const {
217	  auto ret = ge::SUCCESS;
218	  LLM_MAKE_GUARD(send_status, ([fd, &ret]() {
219	                   LLMLinkStatus status{};
220	                   status.error_code = ret;
221	                   LinkMsgHandler::SendMsg(fd, LinkMsgType::kStatus, status);
222	                 }));
223	
224	  LLMDisconnectInfo peer_disconnect_info{};
225	  LLM_CHK_STATUS_RET(LinkMsgHandler::Deserialize(msg, peer_disconnect_info), "Failed to deserialize disconnect msg");
226	  LLMLOGI("Start to process disconnect cluster, local cluster_id:%lu, remote cluster_id:%lu.", cluster_id_,
227	          peer_disconnect_info.cluster_id);
228	  ret = DisconnectInfoProcess(peer_disconnect_info);
229	  if (ret == ge::SUCCESS) {
230	    LLMLOGI("Success to process disconnect cluster, local cluster_id:%lu, remote cluster_id:%lu.", cluster_id_,
231	            peer_disconnect_info.cluster_id);
232	  }
233	  LLM_CHK_STATUS(ret, "Failed to process disconnect info, local cluster_id:%lu, remote cluster_id:%lu", cluster_id_,
234	                 peer_disconnect_info.cluster_id);
235	  return ret;
236	}
237	
238	ge::Status LinkMsgHandler::ConnectedProcess(int32_t fd, bool &keep_fd) {
239	  keep_fd = false;
240	  int32_t msg_type = 0;
241	  std::vector<char> msg;
242	  LLM_CHK_STATUS_RET(MsgHandlerPlugin::RecvMsg(fd, msg_type, msg), "Failed to recv msg");
243	  LLM_CHK_BOOL_RET_STATUS(static_cast<LinkMsgType>(msg_type) == LinkMsgType::kConnect ||
244	                              static_cast<LinkMsgType>(msg_type) == LinkMsgType::kDisconnect,
245	                          ge::LLM_PARAM_INVALID, "Failed to check msg type:%d", msg_type);
246	
247	  if (static_cast<LinkMsgType>(msg_type) == LinkMsgType::kConnect) {
248	    LLM_CHK_STATUS_RET(ProcessConnectRequest(fd, msg), "Failed to process connect request");
249	  } else {
250	    LLM_CHK_STATUS_RET(ProcessDisconnectRequest(fd, msg), "Failed to process disconnect request");
251	  }
252	  return ge::SUCCESS;
253	}
