255	ge::Status LinkMsgHandler::SetEntityMemInfo(const LLMExchangeInfo &peer_exchange_info, EntityPtr entity,
256	                                            EntityMemInfoPtr &mem_info_ptr) const {
257	  // prepare mem
258	  entity->SetEntityMemInfo(mem_info_ptr);
259	  auto &remote_mems = entity->GetRemoteMems();
260	  CommMem remote_mem{};
261	  remote_mem.type = CommMemType::COMM_MEM_TYPE_DEVICE;
262	  remote_mem.addr = ValueToPtr(peer_exchange_info.cache_table_addr);
263	  remote_mem.size = peer_exchange_info.cache_table_size;
264	  remote_mems.emplace_back(remote_mem);
265	  remote_mem.type = CommMemType::COMM_MEM_TYPE_HOST;
266	  remote_mem.addr = ValueToPtr(peer_exchange_info.req_addr);
267	  remote_mem.size = peer_exchange_info.req_size;
268	  remote_mems.emplace_back(remote_mem);
269	  remote_mem.type = CommMemType::COMM_MEM_TYPE_HOST;
270	  remote_mem.addr = ValueToPtr(peer_exchange_info.resp_addr);
271	  remote_mem.size = peer_exchange_info.resp_size;
272	  remote_mems.emplace_back(remote_mem);
273	  LLM_CHK_STATUS_RET(entity->SetInfo(), "Failed to set entity mem info");
274	  entity->MarkEntityIdle();
275	  return ge::SUCCESS;
276	}
277	
278	ge::Status LinkMsgHandler::GenerateRankInfo(const std::string &peer_comm_res, std::string &rank_table,
279	                                            int32_t &local_rank_id, int32_t &peer_rank_id) const {
280	  auto rank_table_generator = RankTableGeneratorFactory::Create(local_comm_res_, peer_comm_res);
281	  LLM_CHK_BOOL_RET_STATUS(rank_table_generator != nullptr, ge::LLM_PARAM_INVALID,
282	                          "Failed to create rank table generator.");
283	  LLM_CHK_STATUS_RET(rank_table_generator->Generate(device_id_, rank_table), "Failed to generate rank table");
284	  local_rank_id = rank_table_generator->GetLocalRankId();
285	  LLM_CHK_BOOL_RET_STATUS(local_rank_id >= 0, ge::LLM_PARAM_INVALID,
286	                          "Failed to get local rank id, please check rank table.");
287	  peer_rank_id = rank_table_generator->GetPeerRankId();
288	  return ge::SUCCESS;
289	}
290	
291	ge::Status LinkMsgHandler::ExchangeInfoProcess(const LLMExchangeInfo &peer_exchange_info, int32_t timeout,
292	                                               bool force_link, EntityMemInfoPtr &mem_info_ptr) const {
293	  LLM_CHK_BOOL_RET_STATUS(peer_exchange_info.cache_table_size <= kCacheAccessTableBufferSize, ge::LLM_PARAM_INVALID,
294	                          "Remote cache_table_size %lu exceeds max %lu.", peer_exchange_info.cache_table_size,
295	                          kCacheAccessTableBufferSize);
296	  int32_t local_rank_id = -1;
297	  int32_t peer_rank_id = -1;
298	  std::string rank_table;
299	  LLM_CHK_STATUS_RET(GenerateRankInfo(peer_exchange_info.comm_res, rank_table, local_rank_id, peer_rank_id),
300	                     "Failed to generate rank info");
301	  if (force_link) {
302	    LLM_CHK_STATUS_RET(comm_entity_manager_->DestroyEntity(peer_exchange_info.cluster_id),
303	                       "Failed to destroy previous entity, peer cluster id:%lu.", peer_exchange_info.cluster_id);
304	  }
305	
306	  auto entity = comm_entity_manager_->GetEntityByRemoteClusterId(peer_exchange_info.cluster_id);
307	  LLM_CHK_BOOL_RET_STATUS(entity == nullptr, ge::LLM_ALREADY_LINK, "Link already exists, peer cluster id:%lu.",
308	                          peer_exchange_info.cluster_id);
309	
310	  entity = MakeShared<CommEntity>(UINT64_MAX, peer_exchange_info.cluster_id, peer_rank_id, cluster_id_, local_rank_id);
311	  LLM_CHECK_NOTNULL(entity);
312	  LLM_CHK_STATUS_RET(entity->Initialize(remote_cache_accessible_), "Failed to init entity");
313	  ScopeGuard entity_guard([entity]() { entity->Finalize(); });
314	  EntityCommInfo::CommParams comm_params{};
315	  comm_params.rank_id = local_rank_id;
316	  comm_params.comm_config = comm_config_;
317	  LLM_ASSERT_EOK(
318	      strcpy_s(comm_params.comm_config.hcclCommName, COMM_NAME_MAX_LENGTH, peer_exchange_info.comm_name.c_str()));
319	  comm_params.rank_table = rank_table;
320	  comm_params.mem_handles = mem_handles_callback_();
321	  constexpr uint32_t kTimeInSec = 1000;
322	  auto left_time = timeout % kTimeInSec == 0 ? 0 : 1;
323	  comm_params.timeout = timeout / kTimeInSec + left_time;
324	  auto comm_info_ptr = MakeShared<EntityCommInfo>(comm_params);
325	  LLM_CHECK_NOTNULL(comm_info_ptr);
326	  LLM_CHK_STATUS_RET(comm_info_ptr->Initialize(), "Failed to init communication.");
327	  entity->SetEntityCommInfo(comm_info_ptr);
328	  entity->SetContext(aclrt_context_);
329	  entity->SetCacheManager(cache_manager_);
330	  LLM_CHK_STATUS_RET(SetEntityMemInfo(peer_exchange_info, entity, mem_info_ptr), "Failed ti set entity mem info");
331	  LLMLOGI("Success to create comm entity:%s", entity->GetDesc().c_str());
332	  LLM_CHK_STATUS_RET(comm_entity_manager_->AddEntity(peer_exchange_info.cluster_id, entity), "Failed to add entity");
333	  entity_guard.Dismiss();
334	  return ge::SUCCESS;
335	}
336	
337	ge::Status LinkMsgHandler::GenerateLocalCommRes(const ClusterInfo &cluster) {
338	  std::lock_guard<std::mutex> lock(mutex_);
339	  if (!local_comm_res_.empty()) {
340	    return ge::SUCCESS;
341	  }
342	  LLM_CHK_BOOL_RET_STATUS(cluster.local_ip_infos.size() == 1U, ge::LLM_PARAM_INVALID,
343	                          "In scenarios where local comm res is not configured, "
344	                          "local_ip_infos must be specified and only supports a size of 1.");
345	  LLM_CHK_STATUS_RET(LLMUtils::IntToIp(cluster.local_ip_infos[0].ip, local_ip_), "Failed to convert local ip.");
346	  LLM_CHK_STATUS_RET(LocalCommResGenerator::Generate(local_ip_, device_id_, local_comm_res_),
347	                     "Failed to generate local comm res, local_ip:%s, device_id:%d", local_ip_.c_str(), device_id_);
348	  return ge::SUCCESS;
349	}
