355	ge::Status LinkMsgHandler::CreateEntityMemInfo(EntityMemInfoPtr &mem_info_ptr) const {
356	  mem_info_ptr = MakeUnique<EntityMemInfo>(remote_cache_accessible_, comm_entity_manager_->GetHostRegPool(),
357	                                           comm_entity_manager_->GetDeviceRegPool());
358	  LLM_CHECK_NOTNULL(mem_info_ptr);
359	  LLM_CHK_STATUS_RET(mem_info_ptr->Initialize(), "Failed to init mem info");
360	  return ge::SUCCESS;
361	}
362	
363	ge::Status LinkMsgHandler::LinkCluster(const ClusterInfo &cluster, int32_t timeout) {
364	  LLM_CHK_BOOL_RET_STATUS(cluster.remote_ip_infos.size() == 1U, ge::LLM_PARAM_INVALID,
365	                          "remote_ip_infos size != 1 is unsupported.");
366	  std::string remote_ip_str;
367	  LLM_CHK_STATUS_RET(LLMUtils::IntToIp(cluster.remote_ip_infos[0].ip, remote_ip_str), "Failed to convert remote ip.");
368	  LLM_CHK_STATUS_RET(GenerateLocalCommRes(cluster), "Failed to generate local comm res");
369	  int32_t conn_fd = 0;
370	  uint32_t remote_port = static_cast<uint32_t>(cluster.remote_ip_infos[0].port);
371	  LLMLOGI("Start to link cluster, local cluster_id:%lu, remote info %s:%u, timeout:%d ms.", cluster_id_,
372	          remote_ip_str.c_str(), remote_port, timeout);
373	  LLM_CHK_STATUS_RET(MsgHandlerPlugin::Connect(remote_ip_str, remote_port, conn_fd, timeout, ge::LLM_LINK_FAILED),
374	                     "Failed to connect remote addr %s:%u, timeout=%d ms.", remote_ip_str.c_str(), remote_port,
375	                     timeout);
376	  LLMLOGI("connect to remote addr %s:%u success", remote_ip_str.c_str(), remote_port);
377	
378	  LLM_MAKE_GUARD(close_fd, ([conn_fd]() { MsgHandlerPlugin::Disconnect(conn_fd); }));
379	  EntityMemInfoPtr mem_info_ptr = nullptr;
380	  LLM_CHK_STATUS_RET(CreateEntityMemInfo(mem_info_ptr), "Failed to create entity mem info");
381	  LLMExchangeInfo exchange_info = {};
382	  const auto &buffer_and_size = cache_manager_->GetCacheTableBufferAndSize();
383	  exchange_info.cache_table_addr = PtrToValue(buffer_and_size.first);
384	  exchange_info.cache_table_size = static_cast<uint64_t>(buffer_and_size.second);
385	  exchange_info.comm_res = local_comm_res_;
386	  exchange_info.cluster_id = cluster_id_;
387	  exchange_info.timeout = timeout;
388	  // The local comm does not exist; force the peer link if the peer comm exists.
389	  exchange_info.force_link = comm_entity_manager_->GetEntityByRemoteClusterId(cluster.remote_cluster_id) == nullptr;
390	  exchange_info.req_addr = PtrToValue(mem_info_ptr->req_);
391	  exchange_info.req_size = kDefaultReqBufferSize;
392	  exchange_info.resp_addr = PtrToValue(mem_info_ptr->resp_);
393	  exchange_info.resp_size = kDefaultRespBufferSize;
394	
395	  LLM_CHK_STATUS_RET(SendMsg(conn_fd, LinkMsgType::kConnect, exchange_info), "Failed to send connect msg");
396	  LLMExchangeInfo peer_exchange_info = {};
397	  LLM_CHK_STATUS_RET(RecvMsg(conn_fd, LinkMsgType::kConnect, peer_exchange_info), "Failed to recv connect msg");
398	
399	  peer_exchange_info.comm_name =
400	      "llm_datadist_" + std::to_string(cluster_id_) + "_" + std::to_string(peer_exchange_info.cluster_id);
401	  // 使用 exchange_info.force_link 而非硬编码 false：自连接场景下，服务端 daemon 线程可能先于客户端
402	  // 完成 AddEntity，导致客户端 ExchangeInfoProcess 命中 ALREADY_LINK。传 true 可在本地已存在 entity
403	  // 时先 destroy 再重建，规避竞态；首次建链本地无 entity 时 DestroyEntity 返回 SUCCESS，行为不变。
404	  auto ret = ExchangeInfoProcess(peer_exchange_info, timeout, exchange_info.force_link, mem_info_ptr);
405	  LLMLinkStatus status{};
406	  LLM_CHK_STATUS_RET(RecvMsg(conn_fd, LinkMsgType::kStatus, status), "Failed to recv status msg");
407	  LLM_CHK_STATUS_RET(status.error_code, "Failed to check peer process ret status, error code[%u], err msg[%s]",
408	                     status.error_code, status.error_message.c_str());
409	  LLM_CHK_STATUS_RET(ret, "Failed to process peer exchange info, timeout:%d", timeout);
410	  LLMLOGI("Link cluster success, local cluster_id:%lu, remote cluster_id:%lu, remote ip:%s, remote port:%u",
411	          cluster_id_, peer_exchange_info.cluster_id, remote_ip_str.c_str(), remote_port);
412	  return ge::SUCCESS;
413	}
414	
415	ge::Status LinkMsgHandler::UnlinkCluster(const ClusterInfo &cluster, int32_t timeout, bool force_flag) const {
416	  LLMLOGI("Start to unlink cluster, local cluster_id:%lu, remote cluster_id:%lu, timeout:%d ms, force_flag:%d",
417	          cluster_id_, cluster.remote_cluster_id, timeout, static_cast<int32_t>(force_flag));
418	  LLM_CHK_BOOL_RET_STATUS(force_flag || cluster.remote_ip_infos.size() == 1U, ge::LLM_PARAM_INVALID,
419	                          "When force_flag=false, remote_ip_infos size != 1 is unsupported.");
420	  int32_t conn_fd = -1;
421	  LLM_MAKE_GUARD(close_fd, ([&conn_fd]() {
422	                   if (conn_fd != -1) {
423	                     MsgHandlerPlugin::Disconnect(conn_fd);
424	                   }
425	                 }));
426	
427	  if (!force_flag) {
428	    std::string remote_ip_str;
429	    LLM_CHK_STATUS_RET(LLMUtils::IntToIp(cluster.remote_ip_infos[0].ip, remote_ip_str), "Failed to convert remote ip.");
430	    uint32_t remote_port = static_cast<uint32_t>(cluster.remote_ip_infos[0].port);
431	    LLM_CHK_STATUS_RET(MsgHandlerPlugin::Connect(remote_ip_str, remote_port, conn_fd, timeout, ge::LLM_UNLINK_FAILED),
432	                       "Failed to connect remote addr %s:%u, timeout=%d ms.", remote_ip_str.c_str(), remote_port,
433	                       timeout);
434	    LLMLOGI("connect to remote addr %s:%u success", remote_ip_str.c_str(), remote_port);
435	
436	    LLMDisconnectInfo disconnect_info = {};
437	    disconnect_info.cluster_id = cluster_id_;
438	    disconnect_info.timeout = timeout;
439	    LLM_CHK_STATUS_RET(SendMsg(conn_fd, LinkMsgType::kDisconnect, disconnect_info), "Failed to send disconnect msg");
440	  }
441	  LLMDisconnectInfo peer_disconnect_info = {};
442	  peer_disconnect_info.cluster_id = cluster.remote_cluster_id;
443	  peer_disconnect_info.timeout = timeout;
444	
445	  auto ret = DisconnectInfoProcess(peer_disconnect_info);
446	  if (!force_flag) {
447	    LLMLinkStatus status{};
448	    LLM_CHK_STATUS_RET(RecvMsg(conn_fd, LinkMsgType::kStatus, status), "Failed to recv status msg");
449	    LLM_CHK_STATUS_RET(status.error_code, "Failed to check peer process ret status, error code[%u], err msg[%s]",
450	                       status.error_code, status.error_message.c_str());
451	  }
452	  LLM_CHK_STATUS_RET(ret, "Failed to unlink cluster:%lu", cluster.remote_cluster_id);
453	  LLMLOGI("Unlink cluster success, local cluster_id:%lu, remote cluster_id:%lu, force_flag:%d", cluster_id_,
454	          cluster.remote_cluster_id, force_flag);
455	  return ge::SUCCESS;
456	}
457	
458	size_t LinkMsgHandler::GetLinkSize() const {
459	  return comm_entity_manager_->GetEntitySize();
460	}
461	
462	void LinkMsgHandler::SetMemHandlesCallback(GetMemHandles callback) {
463	  mem_handles_callback_ = callback;
464	}
465	}  // namespace llm
