21	namespace llm {
22	ge::Status CommEntityManager::AddEntity(uint64_t peer_cluster_id, EntityPtr entity_ptr) {
23	  LLM_CHECK_NOTNULL(entity_ptr, "Entity is null, peer cluster id = %lu", peer_cluster_id);
24	  auto entity_id = entity_id_gen_.fetch_add(1UL, std::memory_order::memory_order_relaxed);
25	  mgr_high_priority_flag_.store(true);
26	  std::lock_guard<std::mutex> lock(mutex_);
27	  (void)entity_map_.emplace(entity_id, entity_ptr);
28	  cluster_id_to_entity_id_[peer_cluster_id] = entity_id;
29	  mgr_high_priority_flag_.store(false);
30	  LLMLOGI("Add entity success, peer cluster id:%lu, entity id:%lu", peer_cluster_id, entity_id);
31	  return ge::SUCCESS;
32	}
33	
34	ge::Status CommEntityManager::DestroyEntity(uint64_t peer_cluster_id) {
35	  std::lock_guard<std::mutex> lock(mutex_);
36	  auto ret = ge::SUCCESS;
37	  const auto &it = cluster_id_to_entity_id_.find(peer_cluster_id);
38	  if (it != cluster_id_to_entity_id_.cend()) {
39	    auto entity_id = it->second;
40	    const auto entity_iter = entity_map_.find(entity_id);
41	    if (entity_iter == entity_map_.cend()) {
42	      cluster_id_to_entity_id_.erase(it);
43	      LLMLOGW("Entity map not found, peer cluster id = %lu, entity id = %lu", peer_cluster_id, entity_id);
44	      return ret;
45	    }
46	    auto entity = entity_iter->second;
47	    LLM_CHECK_NOTNULL(entity, "Entity is null, peer cluster id = %lu, entity id = %lu", peer_cluster_id, entity_id);
48	    std::lock_guard<std::mutex> pull_lock(entity->GetPullMutex());
49	    auto entity_ret = entity->Finalize();
50	    ret = entity_ret != ge::SUCCESS ? entity_ret : ret;
51	    if (start_service_) {
52	      std::lock_guard<std::mutex> process_lock(entity->GetProcessMutex());
53	      entity->MarkEntityDestroyed();
54	    } else {
55	      cluster_id_to_entity_id_.erase(it);
56	      entity_map_.erase(entity_id);
57	    }
58	    LLMLOGI("Destroy entity end, peer cluster id = %lu", peer_cluster_id);
59	  } else {
60	    LLMLOGW("Entity not found, peer cluster id = %lu", peer_cluster_id);
61	  }
62	  return ret;
63	}
64	
65	EntityPtr CommEntityManager::GetEntityByRemoteClusterId(const uint64_t remote_cluster_id) {
66	  std::lock_guard<std::mutex> lock(mutex_);
67	  const auto &it = cluster_id_to_entity_id_.find(remote_cluster_id);
68	  if (it == cluster_id_to_entity_id_.cend()) {
69	    return nullptr;
70	  }
71	  auto entity_id = it->second;
72	  const auto entity_iter = entity_map_.find(entity_id);
73	  if (entity_iter == entity_map_.cend()) {
74	    LLMLOGW("Entity map not found, remote cluster id = %lu, entity id = %lu", remote_cluster_id, entity_id);
75	    return nullptr;
76	  }
77	  auto entity = entity_iter->second;
78	  if (entity == nullptr) {
79	    LLMLOGW("Entity is null, remote cluster id = %lu, entity id = %lu", remote_cluster_id, entity_id);
80	    return nullptr;
81	  }
82	  // destroy or memory not prepared
83	  if (entity->GetCurState() == FsmState::FSM_DESTROYED_STATE || entity->GetCurState() == FsmState::FSM_INIT_STATE) {
84	    return nullptr;
85	  }
86	  return entity;
87	}
88	
89	std::vector<EntityPtr> CommEntityManager::QueryEntityByCommId(uint64_t comm_id) const {
90	  std::vector<EntityPtr> entities;
91	  std::lock_guard<std::mutex> lock(mutex_);
92	  for (auto &entity_pair : entity_map_) {
93	    if (entity_pair.second->GetCommId() == comm_id) {
94	      entities.emplace_back(entity_pair.second);
95	    }
96	  }
97	  return entities;
98	}
99	
100	void CommEntityManager::DeleteEntities() {
101	  std::lock_guard<std::mutex> lock(mutex_);
102	  for (auto it = entity_map_.begin(); it != entity_map_.end();) {
103	    auto entity = it->second;
104	    if (entity->GetCurState() == FsmState::FSM_DESTROYED_STATE) {
105	      cluster_id_to_entity_id_.erase(entity->GetClusterId());
106	      it = entity_map_.erase(it);
107	      continue;
108	    }
109	    it++;
110	  }
111	}
112	
113	size_t CommEntityManager::GetEntitySize() const {
114	  std::lock_guard<std::mutex> lock(mutex_);
115	  size_t num = 0U;
116	  for (auto &entity_pair : entity_map_) {
117	    if (entity_pair.second->GetCurState() != FsmState::FSM_DESTROYED_STATE) {
118	      num++;
119	    }
120	  }
121	  return num;
122	}
123	
124	void CommEntityManager::HandleAllEntities() {
125	  if (mgr_high_priority_flag_.load()) {
126	    return;
127	  }
128	  std::lock_guard<std::mutex> lock(mutex_);
129	  for (auto it = entity_map_.begin(); it != entity_map_.end();) {
130	    auto entity = it->second;
131	    if ((entity->GetCurState() == FsmState::FSM_INIT_STATE) || (entity->GetCurState() == FsmState::FSM_ERROR_STATE)) {
132	      it++;
133	      continue;
134	    }
135	    if (entity->GetProcessMutex().try_lock()) {
136	      std::lock_guard<std::mutex> process_lock(entity->GetProcessMutex(), std::adopt_lock);
137	      if (entity->GetCurState() == FsmState::FSM_DESTROYED_STATE) {
138	        cluster_id_to_entity_id_.erase(entity->GetClusterId());
139	        it = entity_map_.erase(it);
140	        continue;
141	      }
142	      LLM_CHK_BOOL_EXEC(entity->ProcessState() == ge::SUCCESS, entity->MarkEntityError(), "Failed to process state");
143	    }
144	    it++;
145	  }
146	}
147	
148	void CommEntityManager::HandleCacheRequest() {
149	  (void)pthread_setname_np(pthread_self(), "ge_llm_fsm");
150	  LLM_CHK_ACL(aclrtSetCurrentContext(aclrt_context_));
151	  while (running_) {
152	    HandleAllEntities();
153	  }
154	}
155	
156	ge::Status CommEntityManager::Initialize(bool start_service) {
157	  start_service_ = start_service;
158	  if (!start_service) {
159	    LLMLOGI("No need to start FSM thread");
160	    return ge::SUCCESS;
161	  }
162	  LLM_CHK_ACL_RET(aclrtGetCurrentContext(&aclrt_context_));
163	  cache_engine_thread_ = std::thread(&CommEntityManager::HandleCacheRequest, this);
164	  LLM_CHK_STATUS_RET(host_reg_pool_.Initialize(), "Failed to init host reg buffer pool");
165	  LLM_CHK_STATUS_RET(device_reg_pool_.Initialize(), "Failed to init device reg buffer pool");
166	  return ge::SUCCESS;
167	}
168	
169	void CommEntityManager::Finalize() {
170	  LLMLOGI("CommEntityManager finalize start");
171	  running_ = false;
172	  if (cache_engine_thread_.joinable()) {
173	    cache_engine_thread_.join();
174	  }
175	  std::lock_guard<std::mutex> lock(mutex_);
176	  for (auto &entity_pair : entity_map_) {
