91	  merged_rank_table.version = kConfigVersionV1;
92	  merged_rank_table.status = local_rank_table.status;
93	  int32_t rank_id = 0;
94	  for (const auto &it : merged_info) {
95	    const auto &server_id = it.first;
96	    const auto &device_set = it.second;
97	    rank_table_v1::ServerInfo server_info{};
98	    server_info.server_id = server_id;
99	    for (const auto &device : device_set) {
100	      auto device_info = device;
101	      device_info.rank_id = rank_id;
102	      rank_id++;
103	      server_info.device_list.emplace_back(device_info);
104	    }
